SELECT
  f.sales_line_id,
  f.transaction_id,
  f.line_number,
  d.calendar_date AS transaction_date,
  f.transaction_time,
  d.retail_year,
  d.retail_week,
  d.retail_half,
  d.day_name,
  st.store_id,
  st.store_name,
  st.region,
  st.store_format,
  p.product_id,
  p.product_name,
  p.category,
  p.subcategory,
  p.brand,
  p.supplier_name,
  pr.promotion_id,
  pr.promotion_name,
  pr.member_type AS promotion_member_type,
  f.quantity,
  f.unit_price,
  f.gross_amount,
  f.discount_amount,
  f.sales_revenue,
  f.unit_cost,
  f.cost_amount,
  f.margin_amount,
  f.is_promoted,
  f.is_late_arriving,
  f.is_imputed,
  f.dq_status,
  f.dq_rules,
  f.source_file,
  f.source_row
FROM {{ ref('fact_sales') }} AS f
JOIN {{ ref('dim_date') }} AS d
  ON d.date_key = f.date_key
JOIN {{ ref('dim_store') }} AS st
  ON st.store_key = f.store_key
JOIN {{ ref('dim_product') }} AS p
  ON p.product_key = f.product_key
JOIN {{ ref('dim_promotion') }} AS pr
  ON pr.promotion_key = f.promotion_key
